package com.movieticket.repository; import com.movieticket.entity.BookingSeat; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.List; public interface BookingSeatRepository extends JpaRepository<BookingSeat,Long>{@Query("select bs.seat.seatId from BookingSeat bs where bs.booking.show.showId=:showId and bs.booking.bookingStatus=com.movieticket.entity.BookingStatus.CONFIRMED") List<Long> findBookedSeatIds(@Param("showId") Long showId); List<BookingSeat> findByBookingBookingId(Long bookingId);}
